insert into public.word_senses (id, stable_key, word_id, module_id, category_id, meaning_en, meaning_zh, usage_note)
values
  ('d17eb2c4-9cf7-5be0-adb7-9cfa89f5d4d8', 'research_english:general_research:attenuate:verb', '0282b7b2-f085-522d-b80c-4349fc8c9163', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to make an effect, association, or signal weaker', '减弱；降低', 'Common in Results and Discussion when adjustment makes an observed association smaller.'),
  ('22aa7aa2-4ff3-5ef5-85ea-573263c41ddc', 'research_english:general_research:robust:adjective', '2eed2f2b-fa93-59fc-a5dd-0763dc8c821a', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'remaining reliable when assumptions, samples, or analyses change', '稳健的；可靠的', 'Often describes a finding that persists across sensitivity analyses.'),
  ('8f74cc86-f52e-5cae-921e-71ec99f2a358', 'research_english:general_research:elucidate:verb', '13c0a492-c113-5164-94f4-861ba5195adc', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to make a mechanism, process, or relationship clearer', '阐明；解释清楚', 'Used when a study seeks to clarify something that is not fully understood.'),
  ('d6a32c55-0627-55c5-ab38-04056f496fe4', 'research_english:general_research:corroborate:verb', '59fda555-d512-5b45-8899-1950b014e2b6', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to provide additional evidence that supports a result or account', '佐证；为……提供支持证据', 'Signals agreement between independent analyses, methods, or data sources.'),
  ('a0411f7a-7902-5b21-8a26-33bb892c330d', 'research_english:general_research:salient:adjective', '8c99668c-3fa7-5b13-9431-0186f1b1eb7d', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'especially important or noticeable in the current context', '突出的；值得注意的；重要的', 'Salient means noteworthy; it does not mean statistically significant.'),
  ('222d4aa1-6b8d-575d-8ed9-111db12e0f83', 'research_english:general_research:warrant:verb', 'a495a83d-310e-5d3c-b523-2591924fdf79', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to justify or call for a particular action or conclusion', '有必要；值得；使……成为合理之举', 'Often introduces a cautious next step rather than a definitive conclusion.'),
  ('e3c9370e-38d6-5851-8aa8-24fffc54c381', 'research_english:general_research:delineate:verb', '1adafa57-413c-5d45-afc9-fc22e5584303', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to mark, describe, or show the boundary of something precisely', '勾画；界定；清楚标示', 'In figure legends, it often describes lines that mark an analyzed region.'),
  ('99af45d8-c707-5572-8446-162b4a334110', 'research_english:general_research:reconcile:verb', '4652320c-42d6-58f8-871d-3a42a8e8ac4a', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to explain how apparently conflicting findings can fit together', '调和；使相互矛盾的结果得到合理解释', 'Common in Discussion sections when studies appear to disagree.'),
  ('e58ee0dd-d64e-5cf7-ae94-b951d74f6c60', 'research_english:general_research:underpin:verb', '5eb36a0f-3bdb-59a7-8f78-b02b133a196b', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to provide the essential support or basis for something', '构成……的基础；支撑', 'Used for evidence, theory, or design that supports a conclusion or method.'),
  ('d93e5801-3726-5613-8efe-29c3a092ede5', 'research_english:general_research:confer:verb', 'd1a7bbfe-5f5b-5aac-9efe-5664325a5bbc', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to give a property, benefit, or degree of protection', '赋予；带来', 'Frequently used with resistance, protection, benefit, or risk.'),
  ('3bccc52c-b1ce-522c-a221-17584f8a5884', 'research_english:general_research:encompass:verb', '7f6747db-7aa6-5606-982a-f1ac0cd53ac5', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to include several elements within a broader whole', '包含；涵盖', 'Often describes the components of a composite outcome or broad study scope.'),
  ('a8514e9d-5067-5dd4-869f-32c51505c1d8', 'research_english:general_research:facilitate:verb', '6263400d-8507-56f2-bb6b-758ba2660d8e', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to make a process or action easier', '促进；使……更容易', 'Describes something that enables or simplifies a research process.'),
  ('ff15cf84-85e2-55f3-a0ae-7c363f66c089', 'research_english:general_research:infer:verb', '44d35d1c-4a38-5927-8e38-476899f86bf4', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to reach a conclusion from evidence rather than direct observation', '推断；推知', 'Writers often state what can or cannot be inferred from a study design.'),
  ('12c6c55f-d2da-5dd5-84f0-85e24b2cfcde', 'research_english:general_research:pertinent:adjective', 'b67298f9-ed08-5677-93dd-1abd9180024e', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'directly relevant to the subject or decision being considered', '相关的；切题的', 'More selective than related: pertinent details matter to the issue at hand.'),
  ('fe2bf210-d31f-527e-807f-dec4c335d20f', 'research_english:general_research:account-for:phrasal-verb', 'd771d5b9-33c6-590e-8fe7-b9c7b9a55b46', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '1d7c2b11-d6b5-51e0-b98f-3604f3a8751f', 'to include a factor in an analysis so that its influence is considered', '将……纳入考虑；校正', 'In Methods, it often describes how a model handles clustering or covariates.'),
  ('7b69869e-83aa-5ab2-85da-75bcb2279c6d', 'research_english:statistics_methodology:confounding:noun', 'f58fcdc6-15b5-5e3e-8037-df90c6a196c4', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'distortion of an exposure-outcome association by another factor associated with the exposure and affecting the outcome', '混杂；混杂作用', 'A central threat to causal interpretation in observational research.'),
  ('9b0ddb1a-ea13-5d2c-a308-b3663514899d', 'research_english:statistics_methodology:heterogeneity:noun', 'ad0443ad-3f25-5bd9-98e0-beb4ede1dd42', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'variation in effects or characteristics across studies or subgroups', '异质性', 'In meta-analysis, it commonly refers to between-study variation beyond sampling error.'),
  ('470d8bd3-315b-562b-8a32-49b6727537db', 'research_english:statistics_methodology:impute:verb', '6f005c59-4f10-56bb-aee9-c91622434f9e', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'to replace missing data with plausible values estimated under a stated method', '插补；估算并填补缺失值', 'The method and assumptions used for imputation should be reported.'),
  ('a02a7ac2-102b-5923-9f38-541ec6c72176', 'research_english:statistics_methodology:stratify:verb', 'a03aa23b-1f47-510d-a523-01ffa8472d9c', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'to divide or organize observations into defined subgroups called strata', '分层；按层划分', 'Stratification may be used in randomization, analysis, or reporting.'),
  ('d7eae6be-d7e2-5041-a39d-ecbf5ecf99d3', 'research_english:statistics_methodology:interaction:noun', 'c63c763f-5d8e-5918-992c-a5dedf038345', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'a situation in which the effect of one variable depends on another variable', '交互作用', 'An interaction test asks whether an effect differs across levels of another variable.'),
  ('ae468bd9-1d5f-59f6-820d-e15eab1a8120', 'research_english:statistics_methodology:power:noun', 'fad154c3-84b8-5e49-b88f-67337a2f9dca', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2ea63ebe-26b8-5460-b60d-663b588b828e', 'the probability that a study will detect a specified effect if that effect truly exists', '统计功效；把握度', 'Power depends on assumptions including effect size, variability, alpha, and sample size.'),
  ('5d2a4d9f-d07a-5f73-b55f-bbe17496bd8c', 'research_english:bioinformatics:alignment:noun', '2d7d66e3-a131-54ea-85bf-975f07b70375', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'the process of matching sequence reads to a reference or to one another', '序列比对', 'Alignment quality can affect downstream quantification and variant calling.'),
  ('1b43ed9c-d94e-5f94-8355-ec734c18c9b5', 'research_english:bioinformatics:coverage:noun', 'a2aee99e-7262-544a-b036-2f763e04db2c', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'the number or extent of sequence reads representing a genomic position or region', '测序覆盖度；覆盖深度', 'Low coverage generally reduces confidence in calls made at a genomic position.'),
  ('c0ae5d8f-294a-5395-9213-33782410ad4a', 'research_english:bioinformatics:normalization:noun', 'e871bb28-00dd-5002-aa01-83f6295f5ae1', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'adjustment of measurements to reduce specified technical differences between samples', '标准化；归一化', 'Normalization makes values more comparable but does not remove every technical artifact.'),
  ('aa23ef98-df12-57ad-adab-62a1b81cf53b', 'research_english:bioinformatics:differential:adjective', '1aaa2877-3670-5329-9e73-e73655459569', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'showing or testing a measured difference between biological conditions', '差异的；用于比较条件间差异的', 'Common in differential expression or differential abundance analysis.'),
  ('7c03462a-0967-5318-b5c0-6b6d64852305', 'research_english:bioinformatics:enrichment:noun', 'ebc825c7-d23d-55fd-bffa-01d2cdd4937d', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'overrepresentation of a biological feature in a selected set relative to a background', '富集；在选定集合中的占比高于背景预期', 'Enrichment supports overrepresentation; by itself it does not prove pathway activity.'),
  ('f1fd0b13-c2b3-5bd8-b679-e06dde790915', 'research_english:bioinformatics:cluster:noun', 'f6665890-283c-5452-a3f9-9e95ee70355c', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'a data-derived group of cells or observations with similar measured profiles', '聚类；由数据划分出的相似对象组', 'A transcriptional cluster is not automatically equivalent to a biological cell type.'),
  ('b37a052d-5f35-5dac-99ec-d914c8a2ae12', 'research_english:bioinformatics:pseudotime:noun', 'f53f7fee-e20b-5b8a-8198-33c082ed6b27', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'an inferred ordering of cells along a biological trajectory rather than clock time', '伪时间；沿推断生物学轨迹的细胞排序', 'Pseudotime is model-derived and should not be interpreted as directly observed time.'),
  ('87f3a56b-5ca5-578e-90ef-35b0a769a520', 'research_english:bioinformatics:batch-effect:noun', 'b0c95094-cdd0-542f-91dd-80c9732ba3b6', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'systematic technical variation associated with processing groups rather than biology', '批次效应', 'Batch correction should preserve biological variation while addressing specified technical variation.'),
  ('223fadf3-40c3-50eb-9bc6-579acf9c6ad0', 'research_english:bioinformatics:ortholog:noun', '7139e9e5-7e27-5980-a850-c16db87d9925', '5206e1a4-1748-5a36-a1d9-2a0a9f548b64', '2295b0ba-8f8b-5e16-afd8-077f84c8bbc0', 'genes in different species that descended from one ancestral gene through speciation', '直系同源基因', 'Orthologs often, but not always, retain related biological functions.'),
  ('58876225-a216-5465-980c-8d1d83413a36', 'medical_english:anatomy:lumen:noun', 'd5f673e9-d213-5877-ac47-968201007368', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'f2f95a33-ad8a-576c-9ec4-563e8ad57801', 'the inner open space of a hollow organ, vessel, or tube', '管腔；腔内空间', 'Used for the inside space of structures such as vessels, bowel, or ducts.'),
  ('fb7f5ee0-9d7e-5342-b9ab-8d5bf10e9b74', 'medical_english:anatomy:hilum:noun', 'fafa2583-e705-51f3-8dd1-130047c24305', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'f2f95a33-ad8a-576c-9ec4-563e8ad57801', 'an organ region where vessels, nerves, or ducts enter and leave', '门；器官血管、神经或导管出入的部位', 'Common examples include the renal hilum, lung hilum, and splenic hilum.'),
  ('43340896-3164-5db8-96c8-01d04a07f622', 'medical_english:physiology:perfusion:noun', '170b44c7-32a1-5254-a2eb-95836fae48a7', '52d53e9d-b343-50d9-b0d8-059b2540f890', '0419c1eb-5b7b-5fdc-aacb-c4daf1afd345', 'the delivery of blood through tissue to supply oxygen and nutrients', '灌注；组织血流供应', 'Poor perfusion can occur even when a large vessel remains open.'),
  ('869d7ae9-ba6b-54eb-be8b-1d06358ae366', 'medical_english:physiology:compliance:noun', '2c6b36eb-51bb-51ca-8da8-4d3dcaabf447', '52d53e9d-b343-50d9-b0d8-059b2540f890', '0419c1eb-5b7b-5fdc-aacb-c4daf1afd345', 'the ease with which a structure expands in response to pressure', '顺应性；受压后扩张的能力', 'In respiratory physiology, lower lung compliance means stiffer lungs.'),
  ('2fe5b2e3-f981-5f13-99bf-35b609cd4e66', 'medical_english:pathology:necrosis:noun', '976112ef-cfee-5880-8296-f1e48d7f87ce', '52d53e9d-b343-50d9-b0d8-059b2540f890', '3f8e08d5-d603-52c6-a794-038712ff8d03', 'pathologic death of cells or tissue within a living organism', '坏死', 'Necrosis may be described by its pattern, extent, and tissue location.'),
  ('30acf2a2-659b-5f96-85f1-c5e0fcc6a017', 'medical_english:pathology:fibrosis:noun', '6df07b38-5fd8-536c-8fb5-1086c3800a3e', '52d53e9d-b343-50d9-b0d8-059b2540f890', '3f8e08d5-d603-52c6-a794-038712ff8d03', 'excessive deposition of fibrous connective tissue after chronic injury', '纤维化', 'Progressive fibrosis can distort tissue architecture and impair organ function.'),
  ('bf958c53-c00c-5636-b0de-09be9a8d1009', 'medical_english:symptoms:dyspnea:noun', 'cfc60e8a-4955-5357-8f11-8da2c24aca2f', '52d53e9d-b343-50d9-b0d8-059b2540f890', '58a9e7bc-4a47-5465-bf8e-a6312ab0df40', 'a subjective sensation of difficult or uncomfortable breathing', '呼吸困难；气促', 'Dyspnea is a symptom reported by the patient, not a diagnosis by itself.'),
  ('69daf295-f9fc-5c99-a87a-979eb69dda0c', 'medical_english:symptoms:paresthesia:noun', '8b515d46-6e5a-5397-aa13-9f27180f6cf7', '52d53e9d-b343-50d9-b0d8-059b2540f890', '58a9e7bc-4a47-5465-bf8e-a6312ab0df40', 'an abnormal tingling, prickling, or numb sensation without an external stimulus', '感觉异常；麻刺感', 'Patients may describe paresthesia as pins and needles, tingling, or numbness.'),
  ('982b344e-4f9e-5404-9e98-9948814bacb5', 'medical_english:symptoms:satiety:noun', 'a6247528-95bb-54b1-a9d2-49196a13a1c4', '52d53e9d-b343-50d9-b0d8-059b2540f890', '58a9e7bc-4a47-5465-bf8e-a6312ab0df40', 'the feeling of fullness that follows eating', '饱腹感；饱足感', 'Early satiety means feeling full sooner than expected during a meal.'),
  ('fbb02c81-c256-59c4-9565-677c1344ca20', 'medical_english:signs:palpable:adjective', 'deecf41b-a3db-5f0b-8b3c-53a91f9b70ac', '52d53e9d-b343-50d9-b0d8-059b2540f890', '55cae568-79b1-56b4-89eb-8a24ade01c2a', 'able to be felt during physical examination', '可触及的', 'Used for findings detected by palpation rather than inspection alone.'),
  ('2b82d2d5-0989-535a-aade-672432b27605', 'medical_english:signs:pitting-edema:noun', '0a00d7fc-7ef6-5a21-b9c2-92b5b85cb3dd', '52d53e9d-b343-50d9-b0d8-059b2540f890', '55cae568-79b1-56b4-89eb-8a24ade01c2a', 'swelling that retains an indentation after pressure is applied', '凹陷性水肿', 'Its distribution and extent should be documented during examination.'),
  ('32e60700-44a8-5057-85e6-c2dcadb7574f', 'medical_english:diseases:cirrhosis:noun', '0be769fe-d21a-5964-9eaf-68d649680ec4', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a2d7ba65-5cfb-5646-b038-c803f92f88bb', 'advanced chronic liver disease with fibrosis and distorted liver architecture', '肝硬化', 'Cirrhosis can cause portal hypertension and impaired synthetic function.'),
  ('d1077fbb-5ce8-5648-9260-1a26ad745d1d', 'medical_english:diseases:vasculitis:noun', 'fe3ac9dc-9f31-55a1-9fed-c594bbdf262d', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a2d7ba65-5cfb-5646-b038-c803f92f88bb', 'inflammation of blood vessel walls that can injure affected tissues', '血管炎', 'The clinical pattern depends on the size and organs of the affected vessels.'),
  ('86ac04ba-fc14-58b0-97d8-28c7a83dd695', 'medical_english:diagnosis:differential-diagnosis:noun', 'd5d1cae7-ed09-5f26-81d3-e529d050693f', '52d53e9d-b343-50d9-b0d8-059b2540f890', '418fd2cc-1b52-52cd-a6b1-460558fc0fad', 'the set of plausible conditions considered as explanations for a presentation', '鉴别诊断', 'The differential narrows as history, examination, and test results accumulate.'),
  ('3d8637ac-c7f0-5ca5-ac54-545bfddd6bed', 'medical_english:diagnosis:presumptive:adjective', '6a7cfb21-0e80-5643-acd4-ea5db138886d', '52d53e9d-b343-50d9-b0d8-059b2540f890', '418fd2cc-1b52-52cd-a6b1-460558fc0fad', 'considered likely on available evidence but not yet definitively confirmed', '推定的；初步诊断的', 'A presumptive diagnosis may guide urgent care while confirmatory results are pending.'),
  ('67aa8d39-2e26-5a46-a12d-2c982a81076f', 'medical_english:diagnosis:etiology:noun', 'b534a102-6a28-597e-ba6a-9dd4ced50334', '52d53e9d-b343-50d9-b0d8-059b2540f890', '418fd2cc-1b52-52cd-a6b1-460558fc0fad', 'the cause or origin of a disease or clinical condition', '病因；病因学', 'Etiology refers to cause, whereas pathogenesis describes how disease develops.'),
  ('00bcacf3-7d46-5a16-b04d-35bb0d9e3086', 'medical_english:laboratory:leukocytosis:noun', '0ec5fe1c-e0e3-5187-887b-81f4def1828d', '52d53e9d-b343-50d9-b0d8-059b2540f890', '10e2306a-068b-5b0d-be9c-deb0606e5aae', 'a white blood cell count above the reference range', '白细胞增多', 'Leukocytosis is a laboratory finding with infectious, inflammatory, physiologic, and other causes.'),
  ('e23ff8bf-a59b-541c-8bdc-f9ea13a1f8de', 'medical_english:laboratory:hemolyze:verb', 'dd3ea905-1416-556e-893c-f030afdc8f0d', '52d53e9d-b343-50d9-b0d8-059b2540f890', '10e2306a-068b-5b0d-be9c-deb0606e5aae', 'to have red blood cells rupture and release their contents into a specimen', '发生溶血；红细胞破裂', 'A hemolyzed specimen can distort some analyte results and may require recollection.'),
  ('5232a833-e93d-56db-b676-7bf4c5c1c9bd', 'medical_english:imaging:opacity:noun', 'ba7eb08c-0265-5920-a4d8-d1e05e1788fe', '52d53e9d-b343-50d9-b0d8-059b2540f890', '9f6cc5fa-eecd-5d8c-afa7-4ad74c8e4d2e', 'an area that appears whiter or less transparent than surrounding tissue on an image', '影像学密度增高影；不透亮区', 'An opacity is a descriptive imaging finding, not a diagnosis by itself.'),
  ('0063a906-8370-5888-b283-66262821f36b', 'medical_english:imaging:enhancement:noun', '21d4936f-d0bf-5769-899c-d05101f541ec', '52d53e9d-b343-50d9-b0d8-059b2540f890', '9f6cc5fa-eecd-5d8c-afa7-4ad74c8e4d2e', 'an increase in image signal or attenuation after contrast material is given', '强化；增强表现', 'Enhancement describes contrast uptake and does not by itself establish malignancy.'),
  ('d2f92ca9-3db0-5f30-8a60-8128eef85368', 'medical_english:treatment:titrate:verb', '0e5c0ed5-c09f-57b0-9fb5-21b728ee18c6', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'd1c91e1b-3970-5d28-9e17-446cc90b1388', 'to adjust a treatment dose gradually according to response or a measured target', '滴定调整；逐步调节剂量', 'Titration requires a stated response, target, and safety monitoring plan.'),
  ('844f6e17-ed87-52e2-b872-ca28a58315a6', 'medical_english:treatment:supportive-care:noun', 'a47109aa-6112-5741-95b0-bd31e34cbbe5', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'd1c91e1b-3970-5d28-9e17-446cc90b1388', 'care that prevents or relieves symptoms and maintains comfort and function during illness or treatment', '支持治疗；对症支持性照护', 'Supportive care may accompany disease-directed treatment rather than replace it.'),
  ('d6ce0032-659f-584d-8332-364b4d7de319', 'medical_english:treatment:refractory:adjective', 'b6a5959a-b3a9-59ef-a455-dbafe7f2e09f', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'd1c91e1b-3970-5d28-9e17-446cc90b1388', 'not responding adequately to appropriate treatment', '难治的；治疗抵抗的', 'The treatment and adequate exposure should be clear before a condition is called refractory.'),
  ('1d704bbb-0f8e-5ce1-a3fe-b1e87e95de66', 'medical_english:pharmacology:bioavailability:noun', 'f1d3cfd3-5f98-5a10-a7ad-0bcf11d91ac4', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'be176af9-cee2-5fc3-a8c1-dabaf200bb70', 'the fraction of an administered dose that reaches systemic circulation unchanged', '生物利用度', 'Oral bioavailability may be limited by incomplete absorption and first-pass metabolism.'),
  ('49138d3c-465d-5d54-a243-83b37dca45a0', 'medical_english:pharmacology:contraindicate:verb', 'dfa3e02b-c768-581f-a648-857f0618d5ab', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'be176af9-cee2-5fc3-a8c1-dabaf200bb70', 'to make a treatment inadvisable because its expected risk is unacceptable', '禁忌；不宜使用', 'Contraindicated is stronger than use with caution.'),
  ('f4dde3a3-13f9-5fa0-a3ed-82ffd58b5581', 'medical_english:surgery_procedures:debridement:noun', 'e69ca0e9-4949-561e-afbe-d124fdc4e5fe', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'fa342f3d-0091-5406-a280-66eb64166d92', 'removal of dead, damaged, or contaminated tissue from a wound', '清创；清创术', 'Debridement may be surgical, mechanical, autolytic, or enzymatic.'),
  ('090da5f0-16c8-5f63-bf84-ae57f2c16a63', 'medical_english:surgery_procedures:anastomosis:noun', 'a2657799-cb5e-59d3-a241-2041ee484f5f', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'fa342f3d-0091-5406-a280-66eb64166d92', 'a surgically created connection between two tubular structures', '吻合；吻合口', 'The term may refer to the connection itself or the act of creating it.'),
  ('f24a48e6-3df5-588a-bda0-5ca55a10a97c', 'medical_english:clinical_expressions:deny:verb', '7ff42c27-1dc8-5e29-8576-046704cfe58a', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a482bbf8-c44c-590c-a328-562f923f69ae', 'to report that a symptom or history is not present', '否认有；自述没有', 'In a medical record, denies reflects the patient''s report, not independent proof of absence.'),
  ('c559b7eb-1ed1-5cf8-a947-89b01133b86f', 'medical_english:clinical_expressions:unremarkable:adjective', 'd6a98259-0a6d-582e-a8f6-31f3a9e0219b', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a482bbf8-c44c-590c-a328-562f923f69ae', 'showing no important abnormality in the stated examination or test', '未见明显异常的', 'Unremarkable is context-specific and does not mean that every possible condition was excluded.'),
  ('a57e8376-1c69-54e0-9f30-8cd97fb31db4', 'medical_english:clinical_expressions:lost-to-follow-up:phrase', '6f6c50d4-0ecb-58b1-9ae2-f2ab0f505a54', '52d53e9d-b343-50d9-b0d8-059b2540f890', 'a482bbf8-c44c-590c-a328-562f923f69ae', 'no longer available for planned follow-up assessment or contact', '失访；未能继续随访', 'Loss to follow-up can create missing outcome data and selection bias.')
insert into public.contexts (id, stable_key, word_sense_id, context_sentence, target_text, plain_english_paraphrase, sentence_translation_zh, collocations, context_genre, source_type, source_title, source_url, doi, pmid)
values
  ('35546955-b68f-50b2-b4ca-c80d189e8f66', 'research_english:general_research:attenuate:verb:res-general-attenuate-001', 'd17eb2c4-9cf7-5be0-adb7-9cfa89f5d4d8', 'The association was substantially attenuated after adjustment for age and body mass index.', 'attenuated', 'Taking age and body mass index into account made the observed relationship weaker.', '调整年龄和体重指数后，该关联明显减弱。', array['attenuate an association', 'attenuate an effect', 'attenuate a signal']::text[], 'research_results', 'original_example', null, null, null, null),
  ('a7f62db9-dfba-5882-8ca8-b40556411b3e', 'research_english:general_research:robust:adjective:res-general-robust-001', '22aa7aa2-4ff3-5ef5-85ea-573263c41ddc', 'The association remained robust in analyses that excluded participants with pre-existing disease.', 'robust', 'Removing participants who were already ill did not materially change the result.', '排除既往患病的参与者后，该关联仍然稳健。', array['robust finding', 'robust estimate', 'robust evidence']::text[], 'research_results', 'original_example', null, null, null, null),
  ('53ffd066-abc1-5529-a7e9-0d5b3ccb58de', 'research_english:general_research:elucidate:verb:res-general-elucidate-001', '8f74cc86-f52e-5cae-921e-71ec99f2a358', 'Single-cell profiling may elucidate how stromal cells contribute to treatment resistance.', 'elucidate', 'Single-cell data may clarify the part stromal cells play in making treatment less effective.', '单细胞分析可能阐明基质细胞如何促成治疗耐药。', array['elucidate a mechanism', 'elucidate the role', 'elucidate a pathway']::text[], 'research_introduction', 'original_example', null, null, null, null),
  ('8badacaa-7a40-5a98-baad-2b94048d7359', 'research_english:general_research:corroborate:verb:res-general-corroborate-001', 'd6a32c55-0627-55c5-ab38-04056f496fe4', 'The association observed in the discovery cohort was corroborated in an independent sample.', 'corroborated', 'A separate group of participants produced evidence supporting the original result.', '发现队列中观察到的关联在独立样本中得到了佐证。', array['corroborate a finding', 'corroborating evidence', 'independently corroborated']::text[], 'research_results', 'original_example', null, null, null, null),
  ('081e7173-fd0f-56f7-8c6b-5377b0a65566', 'research_english:general_research:salient:adjective:res-general-salient-001', 'a0411f7a-7902-5b21-8a26-33bb892c330d', 'One salient limitation was the absence of repeated dietary measurements during follow-up.', 'salient', 'An important weakness was that the researchers did not measure diet again later.', '一个值得注意的局限是随访期间没有重复测量饮食。', array['salient feature', 'salient limitation', 'clinically salient']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('e41cbafb-3bec-5ba7-9651-284572013b5e', 'research_english:general_research:warrant:verb:res-general-warrant-001', '222d4aa1-6b8d-575d-8ed9-111db12e0f83', 'The modest effect size warrants cautious interpretation rather than an immediate change in practice.', 'warrants', 'Because the effect was small, the result should be interpreted carefully before practice changes.', '效应量较小，因此应谨慎解释，而不宜立即改变实践。', array['warrant further investigation', 'warrant caution', 'warrant consideration']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('ca2fa796-9a5e-55f6-a164-31c96e90220f', 'research_english:general_research:delineate:verb:res-general-delineate-001', 'e3c9370e-38d6-5851-8aa8-24fffc54c381', 'Dashed white lines delineate the tumor boundary used for image quantification.', 'delineate', 'The dashed white lines show exactly where the measured tumor region begins and ends.', '白色虚线标出了用于图像定量分析的肿瘤边界。', array['delineate a boundary', 'delineate a region', 'clearly delineated']::text[], 'figure_legend', 'original_example', null, null, null, null),
  ('e55e19ac-248b-5e44-ad25-871059cdc536', 'research_english:general_research:reconcile:verb:res-general-reconcile-001', '99af45d8-c707-5572-8446-162b4a334110', 'Differences in follow-up duration may help reconcile the apparently conflicting estimates.', 'reconcile', 'The estimates may differ because the studies followed participants for different lengths of time.', '随访时长的差异或许有助于解释这些看似相互矛盾的估计值。', array['reconcile findings', 'reconcile differences', 'difficult to reconcile']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('315d3ff9-f3cc-57ed-a6b1-a1b3c0130b68', 'research_english:general_research:underpin:verb:res-general-underpin-001', 'e58ee0dd-d64e-5cf7-ae94-b951d74f6c60', 'Longitudinal sampling underpins our analysis of changes occurring within the same individual.', 'underpins', 'Repeated samples from each person make it possible to study how that person changes over time.', '纵向采样为分析同一个体内部随时间发生的变化奠定了基础。', array['underpin a conclusion', 'underpin an analysis', 'evidence underpinning']::text[], 'research_abstract', 'original_example', null, null, null, null),
  ('b93eabaa-6677-592e-8950-e198ac06af19', 'research_english:general_research:confer:verb:res-general-confer-001', 'd93e5801-3726-5613-8efe-29c3a092ede5', 'The hydrophilic coating conferred resistance to nonspecific protein binding.', 'conferred', 'The water-attracting coating made the surface less likely to bind proteins nonspecifically.', '亲水涂层赋予了材料抵抗非特异性蛋白结合的能力。', array['confer protection', 'confer resistance', 'confer an advantage']::text[], 'research_results', 'original_example', null, null, null, null),
  ('b1b0d850-68c0-523b-91d9-9e11e8d089ac', 'research_english:general_research:encompass:verb:res-general-encompass-001', '3bccc52c-b1ce-522c-a221-17584f8a5884', 'The composite endpoint encompassed death, nonfatal myocardial infarction, and urgent revascularization.', 'encompassed', 'The combined outcome counted any death, nonfatal heart attack, or urgent procedure to restore blood flow.', '该复合终点包括死亡、非致死性心肌梗死和紧急血运重建。', array['encompass a range', 'encompass multiple domains', 'broadly encompass']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('ca2f6fe0-f56a-5b68-b161-e8547b67108f', 'research_english:general_research:facilitate:verb:res-general-facilitate-001', 'a8514e9d-5067-5dd4-869f-32c51505c1d8', 'Standardized variable names facilitated the merging of data from participating centers.', 'facilitated', 'Using the same variable names made it easier to combine data from all centers.', '标准化变量名称使合并各参与中心的数据更加容易。', array['facilitate data sharing', 'facilitate comparison', 'facilitate implementation']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('76150a76-3ab9-5828-8208-087322677c29', 'research_english:general_research:infer:verb:res-general-infer-001', 'ff15cf84-85e2-55f3-a0ae-7c363f66c089', 'Causal direction cannot be inferred from the cross-sectional association.', 'inferred', 'Because the variables were measured at one time, the study cannot show which one caused the other.', '不能根据这一横断面关联推断因果方向。', array['infer causality', 'infer a relationship', 'reasonably infer']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('2bdefd49-f15b-57c3-a49f-4146789b3445', 'research_english:general_research:pertinent:adjective:res-general-pertinent-001', '12c6c55f-d2da-5dd5-84f0-85e24b2cfcde', 'Additional details pertinent to sample randomization are provided in the Supplementary Methods.', 'pertinent', 'The supplementary section gives more information that is directly relevant to how samples were randomized.', '与样本随机化直接相关的更多细节见补充方法。', array['pertinent information', 'pertinent details', 'clinically pertinent']::text[], 'supplementary_methods', 'original_example', null, null, null, null),
  ('ac4a64e4-d828-5aa3-b961-ded284f902cc', 'research_english:general_research:account-for:phrasal-verb:res-general-account-for-001', 'fe2bf210-d31f-527e-807f-dec4c335d20f', 'The mixed-effects model accounted for clustering of patients within hospitals.', 'accounted for', 'The model allowed for patients from the same hospital to be more similar to one another.', '混合效应模型考虑了患者在医院内的聚类。', array['account for clustering', 'account for variation', 'account for confounders']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('171845c8-9cc5-59ba-8020-7fddd36bc421', 'research_english:statistics_methodology:confounding:noun:res-stat-confounding-001', '7b69869e-83aa-5ab2-85da-75bcb2279c6d', 'Residual confounding cannot be excluded because diet was measured only at baseline.', 'confounding', 'Dietary differences that were not fully measured may still partly explain the association.', '由于仅在基线测量饮食，仍不能排除残余混杂。', array['residual confounding', 'control for confounding', 'potential confounding']::text[], 'research_discussion', 'original_example', null, null, null, null),
  ('3e35f5c2-3190-53e1-b38d-78a07a599b10', 'research_english:statistics_methodology:heterogeneity:noun:res-stat-heterogeneity-001', '9b0ddb1a-ea13-5d2c-a308-b3663514899d', 'Substantial heterogeneity was observed across trials in the pooled analysis.', 'heterogeneity', 'The estimated treatment effects differed considerably among the trials.', '汇总分析显示各试验之间存在较大的异质性。', array['substantial heterogeneity', 'between-study heterogeneity', 'assess heterogeneity']::text[], 'research_results', 'original_example', null, null, null, null),
  ('f8e6ad82-f11c-5352-b6a6-fba018c93ad6', 'research_english:statistics_methodology:impute:verb:res-stat-impute-001', '470d8bd3-315b-562b-8a32-49b6727537db', 'Missing baseline values were imputed using multiple imputation by chained equations.', 'imputed', 'The researchers created several plausible replacements for missing baseline measurements using the observed data.', '采用链式方程多重插补法填补了缺失的基线值。', array['impute missing values', 'multiply imputed data', 'imputation model']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('81b4c9cd-e4d6-56de-8e3b-b8fdaf90ac80', 'research_english:statistics_methodology:stratify:verb:res-stat-stratify-001', 'a02a7ac2-102b-5923-9f38-541ec6c72176', 'Randomization was stratified by study center and disease stage.', 'stratified', 'The random assignment was organized separately within each center and disease-stage group.', '随机分组按研究中心和疾病分期进行分层。', array['stratify by age', 'stratified randomization', 'stratified analysis']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('13e01673-4406-574f-8095-e1ab6cc94772', 'research_english:statistics_methodology:interaction:noun:res-stat-interaction-001', 'd7eae6be-d7e2-5041-a39d-ecbf5ecf99d3', 'There was no evidence of an interaction between treatment assignment and baseline severity.', 'interaction', 'The data did not show that treatment worked differently in patients with different initial severity.', '没有证据表明治疗分组与基线严重程度之间存在交互作用。', array['test for interaction', 'significant interaction', 'treatment-by-subgroup interaction']::text[], 'research_results', 'original_example', null, null, null, null),
  ('eed8b0bc-babe-5f02-bc62-9e7ae1a0f448', 'research_english:statistics_methodology:power:noun:res-stat-power-001', 'ae468bd9-1d5f-59f6-820d-e15eab1a8120', 'The planned sample size provided 90% power to detect a five-point difference between groups.', 'power', 'If a true five-point difference existed, the planned study had a 90% chance of detecting it under its assumptions.', '按计划的样本量，研究有 90% 的把握度检出组间 5 分的差异。', array['statistical power', 'power calculation', 'adequate power']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('090626e0-9ad3-5c11-a147-5361f7e82087', 'research_english:bioinformatics:alignment:noun:res-bio-alignment-001', '5d2a4d9f-d07a-5f73-b55f-bbe17496bd8c', 'Low-quality reads were removed before alignment to the reference genome.', 'alignment', 'Poor-quality reads were discarded before the remaining reads were matched to the reference genome.', '在与参考基因组进行序列比对前，先去除了低质量读段。', array['sequence alignment', 'read alignment', 'alignment rate']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('8b0cc44c-eee3-5ff4-b184-d98edd21f6b7', 'research_english:bioinformatics:coverage:noun:res-bio-coverage-001', '1b43ed9c-d94e-5f94-8355-ec734c18c9b5', 'Variants in regions with sequencing coverage below twenty-fold were excluded from analysis.', 'coverage', 'The analysis omitted variants where fewer than twenty reads represented the genomic region.', '测序覆盖深度低于 20 倍区域内的变异被排除在分析之外。', array['sequencing coverage', 'coverage depth', 'low-coverage region']::text[], 'supplementary_methods', 'original_example', null, null, null, null),
  ('3d4764d4-84d9-5114-adb3-77a4ab042fc3', 'research_english:bioinformatics:normalization:noun:res-bio-normalization-001', 'c0ae5d8f-294a-5395-9213-33782410ad4a', 'Count normalization was performed before gene expression was compared across samples.', 'normalization', 'Read counts were adjusted for technical scale differences before samples were compared.', '在比较不同样本的基因表达之前，对计数数据进行了归一化。', array['count normalization', 'normalization method', 'library-size normalization']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('7edbf991-2fbf-5e4e-a8e3-9cd87f5f1224', 'research_english:bioinformatics:differential:adjective:res-bio-differential-001', 'aa23ef98-df12-57ad-adab-62a1b81cf53b', 'We used differential expression analysis to compare treated and untreated cells.', 'differential', 'The analysis tested which genes had different expression levels after treatment.', '我们采用差异表达分析比较处理组与未处理组细胞。', array['differential expression', 'differential abundance', 'differential analysis']::text[], 'research_results', 'original_example', null, null, null, null),
  ('1a1a6e65-24aa-512e-b6b4-9f42cea1e6be', 'research_english:bioinformatics:enrichment:noun:res-bio-enrichment-001', '7c03462a-0967-5318-b5c0-6b6d64852305', 'Pathway enrichment analysis showed that interferon-response genes were overrepresented among genes upregulated in malignant cells.', 'enrichment', 'Interferon-response genes appeared more often than expected in the list of genes with higher expression in malignant cells.', '通路富集分析显示，恶性细胞上调基因中干扰素反应相关基因的占比高于预期。', array['pathway enrichment', 'gene set enrichment', 'enrichment analysis']::text[], 'research_results', 'original_example', null, null, null, null),
  ('741f71e0-315a-5667-9e1b-23fe5c4393dd', 'research_english:bioinformatics:cluster:noun:res-bio-cluster-001', 'f1fd0b13-c2b3-5bd8-b679-e06dde790915', 'Cells in each transcriptional cluster shared similar expression profiles, but those labels were not assumed to define cell types.', 'cluster', 'Cells grouped together because their gene expression looked similar, although each group was not automatically called a cell type.', '每个转录聚类中的细胞具有相似的表达谱，但并未假定聚类标签必然代表细胞类型。', array['transcriptional cluster', 'cell cluster', 'cluster marker']::text[], 'figure_legend', 'original_example', null, null, null, null),
  ('e39d6a3a-ddad-59d1-a3df-5c8c3ef3515f', 'research_english:bioinformatics:pseudotime:noun:res-bio-pseudotime-001', 'b37a052d-5f35-5dac-99ec-d914c8a2ae12', 'Pseudotime ordered cells along an inferred transition from a progenitor-like to a differentiated state.', 'Pseudotime', 'The method arranged cells by their likely position in a developmental change, not by when they were collected.', '伪时间将细胞沿着从祖细胞样状态向分化状态转变的推断轨迹排序。', array['pseudotime trajectory', 'pseudotime analysis', 'order cells in pseudotime']::text[], 'research_results', 'original_example', null, null, null, null),
  ('422bc3f0-cd90-5397-b70f-320e2c4760bc', 'research_english:bioinformatics:batch-effect:noun:res-bio-batch-effect-001', '87f3a56b-5ca5-578e-90ef-35b0a769a520', 'Batch effects were assessed before libraries prepared on different days were combined.', 'Batch effects', 'The team checked whether preparation day created technical differences before merging the libraries.', '合并不同日期制备的文库前，先评估了批次效应。', array['batch effect', 'correct batch effects', 'batch-associated variation']::text[], 'research_methods', 'original_example', null, null, null, null),
  ('d91764dc-9eb3-5e7a-8255-548ecda5e8c1', 'research_english:bioinformatics:ortholog:noun:res-bio-ortholog-001', '223fadf3-40c3-50eb-9bc6-579acf9c6ad0', 'Human genes were mapped to mouse orthologs before the cross-species comparison.', 'orthologs', 'Each human gene was paired with its evolutionarily corresponding mouse gene before comparison.', '跨物种比较前，将人类基因映射到小鼠直系同源基因。', array['mouse ortholog', 'identify orthologs', 'one-to-one ortholog']::text[], 'supplementary_methods', 'original_example', null, null, null, null),
  ('2ef1bd95-fb61-5ae4-bbd4-5b9e008bfab4', 'medical_english:anatomy:lumen:noun:med-anatomy-lumen-001', '58876225-a216-5465-980c-8d1d83413a36', 'Endoscopy revealed a smooth lesion protruding into the gastric lumen.', 'lumen', 'The camera showed a smooth lesion extending into the open space inside the stomach.', '内镜检查发现一个向胃腔内突出的光滑病变。', array['vascular lumen', 'intestinal lumen', 'narrow the lumen']::text[], 'case_report', 'original_example', null, null, null, null),
  ('cd176aaf-d8f2-5d99-b6ef-f693ce69275c', 'medical_english:anatomy:hilum:noun:med-anatomy-hilum-001', 'fb7f5ee0-9d7e-5342-b9ab-8d5bf10e9b74', 'At the renal hilum, the vein usually lies anterior to the renal artery.', 'hilum', 'Where the kidney''s vessels enter and leave, the vein is usually in front of the artery.', '在肾门处，肾静脉通常位于肾动脉前方。', array['renal hilum', 'pulmonary hilum', 'hilar structures']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('f439d45f-8607-5f7c-921f-7a705f4f5a53', 'medical_english:physiology:perfusion:noun:med-physiology-perfusion-001', '43340896-3164-5db8-96c8-01d04a07f622', 'Mean arterial pressure was maintained to preserve renal perfusion during surgery.', 'perfusion', 'Blood pressure was kept high enough for adequate blood flow through the kidneys during the operation.', '术中维持平均动脉压，以保证肾脏灌注。', array['tissue perfusion', 'renal perfusion', 'impaired perfusion']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('2aca3254-b821-5ea1-a893-db0aa3308a78', 'medical_english:physiology:compliance:noun:med-physiology-compliance-001', '869d7ae9-ba6b-54eb-be8b-1d06358ae366', 'Pulmonary fibrosis reduces lung compliance and increases the work needed to breathe.', 'compliance', 'Scarred lungs are harder to expand, so breathing requires more effort.', '肺纤维化会降低肺顺应性，并增加呼吸做功。', array['lung compliance', 'reduced compliance', 'static compliance']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('6df20019-bc56-5e7a-9afc-afa3425bd509', 'medical_english:pathology:necrosis:noun:med-pathology-necrosis-001', '2fe5b2e3-f981-5f13-99bf-35b609cd4e66', 'Histologic examination showed confluent hepatocyte necrosis around the central veins.', 'necrosis', 'Microscopy showed connected areas of dead liver cells around the central veins.', '组织学检查显示中央静脉周围存在融合性肝细胞坏死。', array['tissue necrosis', 'coagulative necrosis', 'extensive necrosis']::text[], 'case_report', 'original_example', null, null, null, null),
  ('3940c12f-74d5-575a-992c-274217d6444c', 'medical_english:pathology:fibrosis:noun:med-pathology-fibrosis-001', '30acf2a2-659b-5f96-85f1-c5e0fcc6a017', 'Repeated tissue injury can activate fibroblasts and lead to progressive fibrosis.', 'fibrosis', 'Ongoing injury can switch on scar-forming cells and cause increasing scar tissue.', '反复组织损伤可激活成纤维细胞，并导致进行性纤维化。', array['progressive fibrosis', 'tissue fibrosis', 'fibrotic change']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('9795dc73-d2d6-510f-8fb7-339bcd0ac88d', 'medical_english:symptoms:dyspnea:noun:med-symptoms-dyspnea-001', 'bf958c53-c00c-5636-b0de-09be9a8d1009', 'The patient reported progressive dyspnea on exertion but no chest pain at rest.', 'dyspnea', 'The patient had increasing difficulty breathing during activity, although there was no resting chest pain.', '患者诉活动时呼吸困难逐渐加重，但静息时无胸痛。', array['exertional dyspnea', 'acute dyspnea', 'progressive dyspnea']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('29870a5d-55d3-59ac-8017-1cec4d682c48', 'medical_english:symptoms:paresthesia:noun:med-symptoms-paresthesia-001', '69daf295-f9fc-5c99-a87a-979eb69dda0c', 'Intermittent paresthesia in both hands became more noticeable at night.', 'paresthesia', 'The patient sometimes felt tingling or numbness in both hands, especially at night.', '双手间歇性感觉异常在夜间更为明显。', array['distal paresthesia', 'persistent paresthesia', 'report paresthesia']::text[], 'case_report', 'original_example', null, null, null, null),
  ('5efd0d33-0b44-5675-94f1-13fc37c6fed4', 'medical_english:symptoms:satiety:noun:med-symptoms-satiety-001', '982b344e-4f9e-5404-9e98-9948814bacb5', 'She reported early satiety and had begun leaving most of each meal unfinished.', 'satiety', 'She felt full after eating only a small amount and could no longer finish meals.', '她诉早饱，并开始常常无法吃完一顿饭。', array['early satiety', 'postprandial satiety', 'reduced satiety']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('3e3ee9c1-1d9a-5458-9eb3-60d9ce961e6a', 'medical_english:signs:palpable:adjective:med-signs-palpable-001', 'fbb02c81-c256-59c4-9565-677c1344ca20', 'A firm, non-tender mass was palpable in the right upper quadrant.', 'palpable', 'The examiner could feel a firm mass in the right upper abdomen, and it was not painful when pressed.', '右上腹可触及一个质硬、无压痛的肿块。', array['palpable mass', 'palpable lymph node', 'palpable pulse']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('ed6175ba-f388-58a4-a5d3-97971cb456dc', 'medical_english:signs:pitting-edema:noun:med-signs-pitting-edema-001', '2b82d2d5-0989-535a-aade-672432b27605', 'Bilateral pitting edema extended to the mid-shin on examination.', 'pitting edema', 'Both lower legs were swollen, and pressing the skin left a temporary dent up to the middle of the shin.', '查体见双侧凹陷性水肿延伸至小腿中段。', array['bilateral pitting edema', 'dependent edema', 'assess for pitting']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('646f4df3-91e2-5d3a-9474-416fa54460ea', 'medical_english:diseases:cirrhosis:noun:med-diseases-cirrhosis-001', '32e60700-44a8-5057-85e6-c2dcadb7574f', 'In advanced cirrhosis, portal hypertension may lead to ascites and variceal bleeding.', 'cirrhosis', 'Severe long-term liver scarring can raise pressure in the portal circulation, causing abdominal fluid or bleeding veins.', '在晚期肝硬化中，门静脉高压可导致腹水和静脉曲张出血。', array['decompensated cirrhosis', 'alcohol-related cirrhosis', 'cirrhosis complications']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('41c0a84d-6b0d-5e32-aa89-6dda3235c427', 'medical_english:diseases:vasculitis:noun:med-diseases-vasculitis-001', 'd1077fbb-5ce8-5648-9260-1a26ad745d1d', 'Vasculitis was suspected when palpable purpura was accompanied by declining kidney function.', 'Vasculitis', 'Inflamed blood vessels were considered because the patient had raised purple spots and worsening kidney function.', '当可触性紫癜伴肾功能下降时，医生怀疑血管炎。', array['systemic vasculitis', 'small-vessel vasculitis', 'vasculitic rash']::text[], 'case_report', 'original_example', null, null, null, null),
  ('3c3268cb-c36f-5897-98a7-1a54e08a8c84', 'medical_english:diagnosis:differential-diagnosis:noun:med-diagnosis-differential-001', '86ac04ba-fc14-58b0-97d8-28c7a83dd695', 'The differential diagnosis for sudden unilateral weakness included stroke, seizure, and hypoglycemia.', 'differential diagnosis', 'The team considered stroke, seizure, and low blood glucose as possible explanations for the sudden one-sided weakness.', '突发单侧无力的鉴别诊断包括卒中、癫痫发作和低血糖。', array['broad differential diagnosis', 'narrow the differential', 'include in the differential']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('106647f7-07f4-57cf-b241-aed5c5066db9', 'medical_english:diagnosis:presumptive:adjective:med-diagnosis-presumptive-001', '3d8637ac-c7f0-5ca5-ac54-545bfddd6bed', 'A presumptive diagnosis of bacterial meningitis was made while culture results were pending.', 'presumptive', 'The team considered bacterial meningitis likely before the culture had confirmed it.', '在培养结果尚未回报时，医生作出了细菌性脑膜炎的推定诊断。', array['presumptive diagnosis', 'presumptive evidence', 'presumptive treatment']::text[], 'case_report', 'original_example', null, null, null, null),
  ('600a9e6c-70c6-5ae7-afcf-b5e18dff0d2c', 'medical_english:diagnosis:etiology:noun:med-diagnosis-etiology-001', '67aa8d39-2e26-5a46-a12d-2c982a81076f', 'Despite extensive testing, the etiology of the recurrent pancreatitis remained unclear.', 'etiology', 'Even after many tests, clinicians could not determine what was causing the repeated pancreatitis.', '尽管进行了广泛检查，复发性胰腺炎的病因仍不明确。', array['underlying etiology', 'unknown etiology', 'determine the etiology']::text[], 'case_report', 'original_example', null, null, null, null),
  ('b8312fa7-b7e3-56b7-9029-eae56b85d59f', 'medical_english:laboratory:leukocytosis:noun:med-laboratory-leukocytosis-001', '00bcacf3-7d46-5a16-b04d-35bb0d9e3086', 'The complete blood count showed neutrophil-predominant leukocytosis.', 'leukocytosis', 'The blood test showed too many white blood cells, mostly neutrophils.', '血常规显示以中性粒细胞为主的白细胞增多。', array['marked leukocytosis', 'neutrophilic leukocytosis', 'persistent leukocytosis']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('a2432d80-16ae-5888-a828-750ea0fa2577', 'medical_english:laboratory:hemolyze:verb:med-laboratory-hemolyzed-001', 'e23ff8bf-a59b-541c-8bdc-f9ea13a1f8de', 'The potassium result was not reported because the blood specimen was markedly hemolyzed.', 'hemolyzed', 'The laboratory withheld the potassium value because many red blood cells had broken in the sample.', '由于血液标本明显溶血，实验室未报告血钾结果。', array['hemolyzed specimen', 'grossly hemolyzed', 'sample hemolysis']::text[], 'laboratory_report', 'original_example', null, null, null, null),
  ('e3c5e3c3-2199-5059-9788-a5bcca80530b', 'medical_english:imaging:opacity:noun:med-imaging-opacity-001', '5232a833-e93d-56db-b676-7bf4c5c1c9bd', 'The chest radiograph showed a new focal opacity in the right lower lobe.', 'opacity', 'The chest X-ray showed a new localized white area in the lower part of the right lung.', '胸部 X 线片显示右下叶新出现局灶性密度增高影。', array['focal opacity', 'ground-glass opacity', 'airspace opacity']::text[], 'imaging_report', 'original_example', null, null, null, null),
  ('5566382f-d7a6-52bb-a0f5-d37268473c96', 'medical_english:imaging:enhancement:noun:med-imaging-enhancement-001', '0063a906-8370-5888-b283-66262821f36b', 'Contrast-enhanced computed tomography showed peripheral rim enhancement around the collection.', 'enhancement', 'After contrast was given, the scan showed a brighter ring around the fluid collection.', '增强 CT 显示该积液周围存在周边环形强化。', array['contrast enhancement', 'rim enhancement', 'enhancement pattern']::text[], 'imaging_report', 'original_example', null, null, null, null),
  ('7d06ae69-f46a-506d-bb3c-8d500e906e3e', 'medical_english:treatment:titrate:verb:med-treatment-titrate-001', 'd2f92ca9-3db0-5f30-8a60-8128eef85368', 'The dose should be titrated gradually according to symptom control and blood pressure.', 'titrated', 'The dose should be changed in small steps based on whether symptoms improve and blood pressure remains safe.', '应根据症状控制情况和血压逐步调整剂量。', array['titrate the dose', 'titrate to effect', 'careful titration']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('ac98714f-2c23-590d-89cd-314adbe2005c', 'medical_english:treatment:supportive-care:noun:med-treatment-supportive-001', '844f6e17-ed87-52e2-b872-ca28a58315a6', 'Supportive care included oral fluids, antiemetics, and monitoring while the viral illness resolved.', 'Supportive care', 'The patient received fluids, medicine for nausea, and observation while recovering from the virus.', '在病毒性疾病恢复期间，支持治疗包括口服补液、止吐药和监测。', array['supportive care', 'supportive treatment', 'provide supportive care']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('785e19bf-6062-5e35-afe1-bcff0388dc78', 'medical_english:treatment:refractory:adjective:med-treatment-refractory-001', 'd6ce0032-659f-584d-8332-364b4d7de319', 'Her neuropathic pain remained refractory to two appropriately dosed first-line medications.', 'refractory', 'The nerve pain did not improve despite proper doses of two standard first treatments.', '尽管足量使用了两种一线药物，她的神经病理性疼痛仍然难治。', array['refractory pain', 'treatment-refractory', 'refractory to therapy']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('b89db777-f2f1-5bcf-b955-5dd7c2dd2b9f', 'medical_english:pharmacology:bioavailability:noun:med-pharmacology-bioavailability-001', '1d704bbb-0f8e-5ce1-a3fe-b1e87e95de66', 'Extensive first-pass metabolism reduces the oral bioavailability of the drug.', 'bioavailability', 'The body metabolizes much of the swallowed drug before it reaches the general bloodstream unchanged.', '广泛的首过代谢降低了该药物的口服生物利用度。', array['oral bioavailability', 'absolute bioavailability', 'increase bioavailability']::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('a052e2da-6b4c-5e1f-8b81-a8a13d147eac', 'medical_english:pharmacology:contraindicate:verb:med-pharmacology-contraindicated-001', '49138d3c-465d-5d54-a243-83b37dca45a0', 'Re-exposure is contraindicated in a patient with prior anaphylaxis to the same medication.', 'contraindicated', 'The patient must not receive the medicine again after a previous severe allergic reaction to it.', '既往对同一药物发生过严重全身性过敏反应的患者禁忌再次使用该药。', array['absolutely contraindicated', 'contraindicated in pregnancy', 'formal contraindication']::text[], 'clinical_guideline', 'original_example', null, null, null, null),
  ('96204ddc-fc25-5f04-aa1a-74efd35e19b1', 'medical_english:surgery_procedures:debridement:noun:med-surgery-debridement-001', 'f4dde3a3-13f9-5fa0-a3ed-82ffd58b5581', 'Surgical debridement was completed before negative-pressure wound therapy was applied.', 'debridement', 'The surgeon removed unhealthy tissue before placing the wound under suction-assisted treatment.', '完成外科清创后，应用了负压伤口治疗。', array['surgical debridement', 'wound debridement', 'sharp debridement']::text[], 'operative_note', 'original_example', null, null, null, null),
  ('f0115046-71f8-56f1-8581-34c701709792', 'medical_english:surgery_procedures:anastomosis:noun:med-surgery-anastomosis-001', '090da5f0-16c8-5f63-bf84-ae57f2c16a63', 'The bowel anastomosis was inspected for bleeding and leakage before abdominal closure.', 'anastomosis', 'Before closing the abdomen, the surgeon checked the joined bowel ends for bleeding or leaks.', '关闭腹腔前，检查了肠吻合口有无出血和渗漏。', array['bowel anastomosis', 'anastomotic leak', 'create an anastomosis']::text[], 'operative_note', 'original_example', null, null, null, null),
  ('2c724b17-a18d-5e88-b926-001c3ca64b6f', 'medical_english:clinical_expressions:deny:verb:med-clinical-deny-001', 'f24a48e6-3df5-588a-bda0-5ca55a10a97c', 'The patient denies fever, recent travel, or contact with anyone known to be ill.', 'denies', 'The patient says there has been no fever, recent travel, or known exposure to a sick person.', '患者否认发热、近期旅行史或与已知患病者接触。', array['denies chest pain', 'denies any history of', 'patient denies']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('63b356ef-26e9-5120-a7c8-26ef6146a5d2', 'medical_english:clinical_expressions:unremarkable:adjective:med-clinical-unremarkable-001', 'c559b7eb-1ed1-5cf8-a947-89b01133b86f', 'The remainder of the neurological examination was unremarkable.', 'unremarkable', 'No important abnormality was found in the rest of the nervous-system examination.', '其余神经系统查体未见明显异常。', array['examination was unremarkable', 'otherwise unremarkable', 'unremarkable findings']::text[], 'medical_record', 'original_example', null, null, null, null),
  ('c4da7695-2999-55d3-a5f5-f4924896154f', 'medical_english:clinical_expressions:lost-to-follow-up:phrase:med-clinical-lost-follow-up-001', 'a57e8376-1c69-54e0-9f30-8cd97fb31db4', 'The patient was lost to follow-up after the six-month visit, so later outcomes were unavailable.', 'lost to follow-up', 'After the six-month visit, the care team could no longer contact the patient and had no later results.', '该患者在 6 个月访视后失访，因此无法获得后续结局。', array['lost to follow-up', 'loss to follow-up', 'follow-up visit']::text[], 'case_report', 'original_example', null, null, null, null)
